from collections import deque
def enc(I,O,W,H):
    res=[]
    seen=[[False]*W for _ in range(H)]
    for r in range(H):
        for c in range(W):
            if I[r][c]==0 and not seen[r][c]:
                q=[(r,c)]; seen[r][c]=True; path=True
                while q:
                    a,b=q.pop()
                    if a==0 or b==0 or a>=H-1 or b>=W-1: path=False
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+dy,b+dx
                        if 0<=x<H and 0<=y<W and not seen[x][y]:
                            seen[x][y]=True; q.append((x,y))
                if path:
                    print('enc',r,c); res.append((r,c))
    return res
